import React, { useEffect, useRef } from 'react';
import { useMotionValue, useMotionValueEvent, useReducedMotion, useSpring } from 'motion/react';

// Frame grid generated by scripts/headgrid.py: col 0..COLS-1 = looking viewer's left→right, row = up→down.
const COLS = 11;
const ROWS = 9;
const SIZE = 800; // frame resolution
const frameUrl = (c: number, r: number) => `/head/${c}_${r}.webp`;
const CENTER = frameUrl(COLS >> 1, ROWS >> 1);

const clamp = (v: number) => Math.max(-1, Math.min(1, v));

/** Grid position for a gaze in -1..1: the two columns/rows around it and how far between them. */
const span = (v: number, n: number) => {
  const f = ((v + 1) / 2) * (n - 1);
  const a = Math.min(Math.floor(f), n - 2);
  return [a, a + 1, f - a] as const;
};

/**
 * Tiara's avatar: only the head turns toward the cursor (or the last tap on touch screens).
 * A spring eases the gaze, and the four nearest frames are blended, so the head moves
 * continuously instead of stepping from frame to frame.
 */
export const Portrait: React.FC<{ className?: string }> = ({ className = '' }) => {
  const box = useRef<HTMLDivElement>(null);
  const img = useRef<HTMLImageElement>(null);
  const canvas = useRef<HTMLCanvasElement>(null);
  const rows = useRef<[HTMLCanvasElement, HTMLCanvasElement] | null>(null);
  const reduced = useReducedMotion();
  const spring = { stiffness: 90, damping: 20, mass: 0.6 };
  const gx = useSpring(useMotionValue(0), spring);
  const gy = useSpring(useMotionValue(0), spring);
  const loaded = useRef(new Map<string, HTMLImageElement>());

  // Bilinear blend on a canvas, drawn straight from the spring (no React render per frame).
  const show = () => {
    const out = canvas.current?.getContext('2d');
    if (!out) return;
    const [c0, c1, tx] = span(gx.get(), COLS);
    const [r0, r1, ty] = span(gy.get(), ROWS);
    const get = (c: number, r: number) => {
      const i = loaded.current.get(frameUrl(c, r));
      return i?.complete && i.naturalWidth ? i : null;
    };
    const quad = [get(c0, r0), get(c1, r0), get(c0, r1), get(c1, r1)];
    if (quad.some((i) => !i)) return; // wait until all four are downloaded: never draw a hole
    rows.current ??= [document.createElement('canvas'), document.createElement('canvas')];
    rows.current.forEach((row, k) => {
      row.width = row.height = SIZE; // also clears
      const g = row.getContext('2d')!;
      g.drawImage(quad[k * 2]!, 0, 0);
      g.globalAlpha = tx;
      g.drawImage(quad[k * 2 + 1]!, 0, 0);
    });
    out.clearRect(0, 0, SIZE, SIZE);
    out.globalAlpha = 1;
    out.drawImage(rows.current[0], 0, 0);
    out.globalAlpha = ty;
    out.drawImage(rows.current[1], 0, 0);
    if (img.current) img.current.style.visibility = 'hidden'; // the canvas has taken over
  };
  useMotionValueEvent(gx, 'change', show);
  useMotionValueEvent(gy, 'change', show);

  useEffect(() => {
    if (reduced) return;
    // Preload every frame after the page is up; holding the Image objects keeps them cached.
    const cache = loaded.current;
    const preload = window.setTimeout(() => {
      for (let c = 0; c < COLS; c++)
        for (let r = 0; r < ROWS; r++) {
          const i = new Image();
          i.src = frameUrl(c, r);
          cache.set(i.getAttribute('src')!, i);
        }
    }, 800);

    let lastTouch = 0;
    const lookAt = (x: number, y: number) => {
      const r = box.current?.getBoundingClientRect();
      if (!r) return;
      // Eyes sit roughly 40% down the image.
      gx.set(clamp((x - (r.left + r.width / 2)) / (window.innerWidth / 2)));
      gy.set(clamp((y - (r.top + r.height * 0.4)) / (window.innerHeight / 2)));
    };
    const onMove = (e: PointerEvent) => e.pointerType === 'mouse' && lookAt(e.clientX, e.clientY);
    const onDown = (e: PointerEvent) => {
      if (e.pointerType === 'mouse') return;
      lastTouch = Date.now();
      lookAt(e.clientX, e.clientY);
    };
    const onLeave = () => {
      gx.set(0);
      gy.set(0);
    };

    // Touch screens have no cursor: glance around on her own while idle.
    const glance = window.setInterval(() => {
      if (!matchMedia('(hover: none)').matches || Date.now() - lastTouch < 3000) return;
      const home = Math.random() < 0.35;
      gx.set(home ? 0 : Math.random() * 2 - 1);
      gy.set(home ? 0 : Math.random() * 1.2 - 0.6);
    }, 2600);

    window.addEventListener('pointermove', onMove, { passive: true });
    window.addEventListener('pointerdown', onDown, { passive: true });
    document.documentElement.addEventListener('mouseleave', onLeave);
    return () => {
      window.removeEventListener('pointermove', onMove);
      window.removeEventListener('pointerdown', onDown);
      document.documentElement.removeEventListener('mouseleave', onLeave);
      clearTimeout(preload);
      clearInterval(glance);
    };
  }, [reduced, gx, gy]);

  return (
    <div
      ref={box}
      role="img"
      aria-label="Avatar of Tiara Mamuaya"
      className={`relative aspect-square select-none ${className}`}
    >
      <img
        ref={img}
        src={CENTER}
        alt=""
        draggable={false}
        className="absolute inset-0 size-full object-contain object-bottom"
      />
      <canvas ref={canvas} width={SIZE} height={SIZE} className="absolute inset-0 size-full" />
    </div>
  );
};
